1170	    float* tile,
1171	    int panel
1172	) {
1173	    constexpr int N = 128;
1174	    constexpr int TEAM_WIDTH = 4;
1175	    const int team = threadIdx.x / TEAM_WIDTH;
1176	    const int lane = threadIdx.x % TEAM_WIDTH;
1177	    const int stop = panel + 16;
1178	    const int row = stop + team;
1179	    const bool active = row < N;
1180	    float row_values[4];
1181	    #pragma unroll
1182	    for (int item = 0; item < 4; ++item) {
1183	        row_values[item] = active
1184	            ? tile[row * N + panel + item * TEAM_WIDTH + lane]
1185	            : 0.0f;
1186	    }
1187	    #pragma unroll
1188	    for (int pivot = 0; pivot < 16; ++pivot) {
1189	        float dot = 0.0f;
1190	        #pragma unroll
1191	        for (int item = 0; item < 4; ++item) {
1192	            const int col = item * TEAM_WIDTH + lane;
1193	            if (col < pivot) {
