1195	                    row_values[item],
1196	                    tile[(panel + pivot) * N + panel + col],
1197	                    dot
1198	                );
1199	            }
1200	        }
1201	        dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
1202	        dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
1203	        float original = __shfl_sync(
1204	            0xffffffff,
1205	            row_values[pivot / TEAM_WIDTH],
1206	            pivot % TEAM_WIDTH,
1207	            TEAM_WIDTH
1208	        );
1209	        float solved = lane == 0
1210	            ? (original - dot)
1211	                / tile[(panel + pivot) * N + panel + pivot]
1212	            : 0.0f;
1213	        solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
1214	        if (lane == pivot % TEAM_WIDTH) {
1215	            row_values[pivot / TEAM_WIDTH] = solved;
1216	        }
1217	    }
1218	    if (active) {
1219	        #pragma unroll
1220	        for (int item = 0; item < 4; ++item) {
