const seen = new Set();
const stages = [[], []];
for (let iter=0; iter<4; iter++) {
  const src = new Map(), dst = new Map();
  for (let lane=0; lane<32; lane++) {
    const row = lane >> 2;
    const km = lane & 3;
    const kg = (row + iter) & 3;
    const k = kg * 4 + km;
    const key = `${row},${k}`;
    seen.add(key);
    src.set(k, (src.get(k)||0)+1);
    const bank = row*4+km;
    dst.set(bank,(dst.get(bank)||0)+1);
  }
  stages[0].push({iter, src_max:Math.max(...src.values()), dst_max:Math.max(...dst.values())});
}
const seenSplit = new Set();
for (let half=0;half<2;half++) for(let iter=0;iter<2;iter++) {
 const src=new Map(),dst=new Map();
 for(let lane=0;lane<32;lane++){
   const row=lane>>2, km=lane&3;
   const kg=2*half+((row+iter)&1);
   const k=4*kg+km;
   seenSplit.add(`${row},${k}`);
   src.set(k,(src.get(k)||0)+1);
   const bank=row*4+km;dst.set(bank,(dst.get(bank)||0)+1);
 }
 stages[1].push({half,iter,src_max:Math.max(...src.values()),dst_max:Math.max(...dst.values())});
}
text(JSON.stringify({whole_unique:seen.size,split_unique:seenSplit.size,whole:stages[0],split:stages[1]},null,2));

