function sets(panel,m64=false){
 const stop=panel+16,trailing=128-stop,N=128;
 const old=new Set(),neu=new Set(),stage=[new Set(),new Set()];
 for(let v=0;v<trailing;v++)for(let k=0;k<16;k++){
  const row=stop+v;
  const p=m64?(Math.floor(k/4)*8*N+Math.floor(v/8)*N+(v&7)*4+(k&3)):(Math.floor(k/4)*16*N+Math.floor(row/8)*N+(row&7)*4+(k&3));
  old.add(p);
 }
 for(let w=0;w<16;w++)for(let lane=0;lane<32;lane++){
  const ro=lane>>2,v=w*8+ro;if(v>=trailing)continue;
  for(let ph=0;ph<4;ph++){
   const kg=(ro+ph)&3,k=kg*4+(lane&3),row=stop+v;
   const p=m64?(kg*8*N+w*N+ro*4+(lane&3)):(kg*16*N+Math.floor(row/8)*N+(row&7)*4+(lane&3));
   neu.add(p);
  }
  for(let h=0;h<2;h++)for(let ph=0;ph<2;ph++){
   const kg=2*h+((ro+ph)&1),k=kg*4+(lane&3),row=stop+v;
   const p=m64?(kg*8*N+w*N+ro*4+(lane&3)):(kg*16*N+Math.floor(row/8)*N+(row&7)*4+(lane&3));
   stage[h].add(p);
  }
 }
 return {panel,m64,size:old.size,wholeEq:old.size===neu.size&&[...old].every(x=>neu.has(x)),splitUnionEq:old.size===stage[0].size+stage[1].size&&[...old].every(x=>stage[0].has(x)||stage[1].has(x)),stageOverlap:[...stage[0]].some(x=>stage[1].has(x))};
}
text(JSON.stringify([sets(0),sets(16),sets(32),sets(48,true),sets(64,true),sets(80,true),sets(96,true)],null,2));
